// ENVIRONMENT & TECHNOLOGY — batch 2.
export default [
  // ---------------------------------------------------------------- Climate Science
  { id: 'ENV-025', t: 'Climate Science', d: 3, ty: 'data', s: 90, iq: true, v: '((1.0-0.4)/20)/((0.4-(-0.1))/50)',
    q: 'The table gives approximate global average surface temperature anomalies (difference from a 1951–1980 baseline). How does the rate of warming from 2000 to 2020 compare with the rate from 1950 to 2000?',
    tb: { head: ['Year', '1950', '2000', '2020'], rows: [['Anomaly (°C, approx.)', -0.1, 0.4, 1.0]] },
    o: ['About 3 times faster', 'About the same', 'About half as fast', 'About 10 times faster'], a: 0,
    e: '1950–2000: rise of 0.5 °C in 50 years = 0.01 °C per year. 2000–2020: rise of 0.6 °C in 20 years = 0.03 °C per year. So recent warming is about three times faster — consistent with accelerating greenhouse-gas emissions.',
    m: 'Comparing total changes (0.5 vs 0.6 °C) ignores the very different time spans.',
    h: ['Work out °C per year for each period.', 'Divide the two rates.'] },
  { id: 'ENV-026', t: 'Climate Science', d: 2, ty: 'reasoning', s: 50,
    q: 'What are the two main causes of rising global sea level?',
    o: ['Expansion of seawater as it warms, and melting of glaciers and ice sheets on land', 'Melting of floating sea ice and more rainfall', 'Underwater volcanoes and earthquakes', 'Rivers carrying more sand into the sea'], a: 0,
    e: 'Water expands when heated, so a warmer ocean takes up more volume. Ice on land (mountain glaciers, Greenland, Antarctica) adds new water to the ocean when it melts. Floating sea ice barely affects sea level because it already displaces its own weight of water.',
    m: 'Melting floating sea ice is not a major cause of sea-level rise.',
    h: ['Does water expand when heated?', 'Which ice adds new water to the oceans?'] },
  { id: 'ENV-027', t: 'Climate Science', d: 3, ty: 'reasoning', s: 70, iq: true,
    q: 'Melting of the Greenland and Antarctic ice SHEETS raises sea level, but melting of Arctic SEA ICE barely does. Which principle explains the difference?',
    o: ['Floating sea ice already displaces its own weight of water (Archimedes’ principle); ice on land does not, so its meltwater adds to the ocean.', 'Arctic ice is made of salt.', 'Antarctica is warmer than the Arctic.', 'Sea ice evaporates instead of melting.'], a: 0,
    e: 'A floating body displaces water equal to its own weight. When floating ice melts, it fills almost exactly the volume it was displacing (like an ice cube in a glass). Land ice is supported by rock; when it melts or slides into the sea, the ocean gains water it did not hold before. (Melting sea ice still matters: it lowers Earth’s albedo.)',
    m: '',
    h: ['How much water does a floating object displace?', 'Is ice on land floating?'] },
  { id: 'ENV-028', t: 'Climate Science', d: 3, ty: 'interdisciplinary', s: 70,
    q: 'The oceans absorb about a quarter of the CO₂ released by humans. Why is this harmful to corals and shellfish?',
    o: ['Dissolved CO₂ forms carbonic acid, lowering seawater pH and making it harder for organisms to build calcium carbonate shells and skeletons.', 'CO₂ makes the sea too salty.', 'CO₂ freezes the water around corals.', 'CO₂ increases oxygen levels too much.'], a: 0,
    e: 'CO₂ + H₂O ⇌ H₂CO₃ ⇌ H⁺ + HCO₃⁻. The extra H⁺ ions react with carbonate ions, reducing the carbonate available for building CaCO₃. Ocean surface pH has already fallen from about 8.2 to 8.1 — roughly a 26% increase in H⁺ concentration — threatening coral reefs, oysters and plankton.',
    m: '',
    h: ['What does CO₂ form when it dissolves in water?', 'What are shells made of?'] },
  { id: 'ENV-029', t: 'Climate Science', d: 2, ty: 'mcq', s: 40,
    q: 'What is the main temperature goal of the Paris Agreement (2015) on climate change?',
    o: ['To keep global warming well below 2 °C above pre-industrial levels and try to limit it to 1.5 °C', 'To cool the planet by 5 °C', 'To stop all use of electricity', 'To ban cars worldwide by 2020'], a: 0,
    e: 'Nearly every country agreed to set national targets for reducing greenhouse-gas emissions, aiming to hold warming well below 2 °C and pursue 1.5 °C, with regular reviews to increase ambition. India’s pledges include expanding non-fossil electricity capacity.',
    m: '',
    h: ['Two temperature figures are mentioned in the agreement.'] },
  { id: 'ENV-030', t: 'Climate Science', d: 3, ty: 'what-if', s: 70, iq: true,
    q: 'Large areas of Arctic soil are permanently frozen (permafrost) and contain huge amounts of dead plant matter. What could happen as the Arctic warms?',
    o: ['Thawing soil lets microbes decompose the matter, releasing CO₂ and methane, which cause further warming — a positive feedback.', 'More ice would form, cooling the planet.', 'The soil would absorb all the CO₂ in the air.', 'Nothing, because frozen soil contains no carbon.'], a: 0,
    e: 'Permafrost is estimated to hold roughly twice as much carbon as the atmosphere does today. As it thaws, decomposition releases CO₂ (and methane in waterlogged areas), adding greenhouse gases that warm the Arctic further and thaw more permafrost.',
    m: '',
    h: ['What happens to dead plant matter when it is no longer frozen?', 'Would the released gases cause more or less warming?'] },
  { id: 'ENV-031', t: 'Climate Science', d: 1, ty: 'mcq', s: 25,
    q: 'What is the difference between weather and climate?',
    o: ['Weather is the day-to-day state of the atmosphere; climate is the average weather of a region over a long period (usually 30 years or more).', 'They mean exactly the same thing.', 'Climate changes every day; weather stays the same.', 'Weather applies only to rain.'], a: 0,
    e: 'One cold week is weather; a trend in average temperatures over decades is climate. That is why a single cold winter does not disprove global warming.',
    m: '',
    h: ['Which one describes a long-term average?'] },
  { id: 'ENV-032', t: 'Climate Science', d: 3, ty: 'reasoning', s: 70,
    q: 'Nitrogen (N₂) and oxygen (O₂) make up 99% of dry air but are not greenhouse gases, while CO₂, CH₄ and H₂O are. What is the key difference?',
    o: ['Molecules with three or more atoms (or with unevenly shared electrons) can vibrate in ways that absorb infrared; simple two-atom molecules of the same element cannot.', 'N₂ and O₂ are too heavy to absorb heat.', 'CO₂ is coloured, so it absorbs light.', 'N₂ and O₂ are found only high in the atmosphere.'], a: 0,
    e: 'A molecule absorbs infrared when a vibration changes how its electric charge is distributed. In N₂ and O₂, two identical atoms share electrons equally, and stretching them causes no such change. CO₂, CH₄ and H₂O have bending and asymmetric vibrations that do, so they absorb and re-emit infrared radiation from Earth’s surface.',
    m: '',
    h: ['How many atoms do greenhouse-gas molecules have?', 'What must a vibration change to interact with infrared?'] },
  { id: 'ENV-033', t: 'Climate Science', d: 2, ty: 'mcq', s: 40,
    q: 'Which set lists important human-related sources of methane?',
    o: ['Flooded rice paddies, cattle digestion, landfill sites and leaks from natural gas systems', 'Solar panels, wind turbines and batteries', 'Photosynthesis and planting trees', 'Nuclear power stations only'], a: 0,
    e: 'Methane forms when microbes break down organic matter without oxygen — in flooded fields, the stomachs of cattle, buffaloes and sheep, and buried rubbish — and leaks during coal mining and gas production. It is a powerful but shorter-lived greenhouse gas.',
    m: '',
    h: ['Methane forms where organic matter decays without oxygen.'] },

  // ---------------------------------------------------------------- Biodiversity
  { id: 'ENV-034', t: 'Biodiversity', d: 1, ty: 'mcq', s: 25,
    q: 'Which region of India is recognised as a global biodiversity hotspot?',
    o: ['The Western Ghats', 'The Thar Desert', 'The Deccan Plateau as a whole', 'The Indo-Gangetic plain'], a: 0,
    e: 'Biodiversity hotspots are regions with exceptionally many endemic species that have lost much of their original habitat. India includes parts of four: the Western Ghats (with Sri Lanka), the Himalaya, Indo-Burma and Sundaland (the Nicobar Islands).',
    m: '',
    h: ['It is a mountain range along India’s western coast.'] },
  { id: 'ENV-035', t: 'Biodiversity', d: 2, ty: 'mcq', s: 35,
    q: 'In which year did India launch Project Tiger to protect tigers and their habitats?',
    o: ['1973', '1947', '1992', '2010'], a: 0,
    e: 'Project Tiger began in 1973 with nine reserves. It protects whole ecosystems, because saving a top predator requires protecting its prey and habitat. India now holds most of the world’s wild tigers.',
    m: '',
    h: ['It began in the early 1970s.'] },
  { id: 'ENV-036', t: 'Biodiversity', d: 2, ty: 'mcq', s: 35,
    q: 'The Nilgiri tahr is found naturally only in the southern Western Ghats. Such a species is described as:',
    o: ['endemic', 'invasive', 'extinct', 'migratory'], a: 0,
    e: 'An endemic species occurs naturally in only one geographic area. Endemic species are especially vulnerable: if their habitat is destroyed, they have nowhere else to survive.',
    m: '',
    h: ['It is native to one region only.'] },
  { id: 'ENV-037', t: 'Biodiversity', d: 3, ty: 'reasoning', s: 70, iq: true,
    q: 'Elephants in tropical forests swallow large fruits and disperse their seeds over long distances. Ecologists call such species “keystone species”. Why would losing elephants affect a forest far more than their numbers suggest?',
    o: ['Many tree species depend on them to spread seeds and maintain open clearings, so the forest’s whole composition would change.', 'Elephants are the only animals that eat leaves.', 'Elephants produce oxygen for the forest.', 'Losing any species always has exactly the same effect.'], a: 0,
    e: 'A keystone species has an effect on its ecosystem out of proportion to its abundance. Some large-seeded trees are dispersed almost only by elephants; elephants also open clearings, create water holes and recycle nutrients. Without them, those trees decline and many other species dependent on them follow.',
    m: '',
    h: ['What roles do elephants play besides eating?', 'Which plants depend on them?'] },
  { id: 'ENV-038', t: 'Biodiversity', d: 2, ty: 'mcq', s: 40,
    q: 'Which pair correctly gives one example each of in-situ and ex-situ conservation?',
    o: ['In-situ: a national park; ex-situ: a seed bank', 'In-situ: a zoo; ex-situ: a wildlife sanctuary', 'In-situ: a botanical garden; ex-situ: a biosphere reserve', 'Both: zoos'], a: 0,
    e: 'In-situ conservation protects species in their natural habitats (national parks, sanctuaries, biosphere reserves, sacred groves). Ex-situ conservation keeps them outside their habitats (zoos, botanical gardens, seed and gene banks), often as a backup or for breeding programmes.',
    m: '',
    h: ['“In situ” means “in its original place”.'] },
  { id: 'ENV-039', t: 'Biodiversity', d: 2, ty: 'reasoning', s: 50,
    q: 'Water hyacinth, introduced to India as an ornamental plant, now covers many lakes and rivers in thick mats. Why has it become such a problem?',
    o: ['As an invasive species it grows extremely fast and has few natural enemies here, blocking light and reducing oxygen for native life.', 'It is poisonous to all fish.', 'It is a native plant that suddenly mutated.', 'It removes all salt from water.'], a: 0,
    e: 'Invasive species outcompete native ones when freed from the predators, diseases and competitors that kept them in check in their original range. Water hyacinth can double its area in a couple of weeks; mats block sunlight, clog waterways and, when they decay, use up dissolved oxygen.',
    m: '',
    h: ['What usually controls a species’ population in its native habitat?'] },
  { id: 'ENV-040', t: 'Biodiversity', d: 3, ty: 'what-if', s: 70, iq: true,
    q: 'A new highway splits a large forest into two smaller patches that animals cannot cross. Over many generations, what is a likely genetic consequence for a species such as leopards in each patch?',
    o: ['Each small, isolated population loses genetic diversity and suffers more inbreeding, making it more vulnerable to disease and change.', 'Genetic diversity would increase.', 'The leopards would immediately evolve into new species.', 'There would be no effect, because both patches are still forest.'], a: 0,
    e: 'Small, isolated populations exchange no genes. Over time, random loss of alleles (genetic drift) and inbreeding reduce diversity and fitness. Wildlife corridors and underpasses that reconnect habitats help maintain gene flow.',
    m: '',
    h: ['Can genes still move between the two groups?', 'What happens to genetic diversity in a small, closed population?'] },
  { id: 'ENV-041', t: 'Biodiversity', d: 2, ty: 'mcq', s: 35,
    q: 'What is the IUCN Red List?',
    o: ['A global assessment of species’ risk of extinction, using categories such as Vulnerable, Endangered and Critically Endangered', 'A list of the world’s most dangerous animals', 'A list of plants with red flowers', 'A list of polluted rivers'], a: 0,
    e: 'The International Union for Conservation of Nature assesses species against criteria such as population size and decline. The Great Indian Bustard, for example, is listed as Critically Endangered.',
    m: '',
    h: ['It measures risk of extinction.'] },
  { id: 'ENV-042', t: 'Biodiversity', d: 1, ty: 'mcq', s: 25,
    q: 'The dodo, a flightless bird of Mauritius, became extinct in the 17th century. What were the main causes?',
    o: ['Hunting by humans and animals such as rats and pigs introduced by them', 'An ice age', 'A volcanic eruption', 'Too many predators of its own species'], a: 0,
    e: 'The dodo had evolved with no ground predators, so it was unafraid and nested on the ground. Sailors hunted it, and introduced rats, pigs and monkeys ate its eggs. It vanished within about a century of human arrival — a classic example of human-caused extinction.',
    m: '',
    h: ['What arrived on Mauritius with the sailors?'] },
  { id: 'ENV-043', t: 'Biodiversity', d: 3, ty: 'data', s: 80, iq: true,
    q: 'Scientists counted plant species on several islands of similar climate. What pattern do the data show?',
    tb: { head: ['Island area (km²)', '1', '10', '100', '1000'], rows: [['Number of plant species', 30, 60, 120, 240]] },
    o: ['Each tenfold increase in area doubles the number of species: larger areas support more species, but not in direct proportion.', 'Species number is directly proportional to area.', 'Smaller islands have more species.', 'There is no relationship.'], a: 0,
    e: 'Area rises 10× each step while species only double, so the relationship is not proportional (that would give 300, 3000…). Larger areas hold more habitats and larger populations less likely to die out. The same species–area pattern warns that shrinking habitats lose species.',
    m: 'Direct proportionality would mean ten times the area gives ten times the species.',
    h: ['How much does area change between columns?', 'How much does the number of species change for each tenfold increase in area?'] },

  // ---------------------------------------------------------------- Renewable Energy
  { id: 'ENV-044', t: 'Renewable Energy', d: 1, ty: 'mcq', s: 25,
    q: 'What does a solar (photovoltaic) cell do?',
    o: ['Converts light directly into electricity', 'Converts heat into light', 'Stores electricity like a battery', 'Burns fuel using sunlight'], a: 0,
    e: 'In a photovoltaic cell, usually made of silicon, light knocks electrons free and the cell’s internal electric field drives them round a circuit as current. No fuel is burnt and there are no moving parts.',
    m: '',
    h: ['“Photo” means light; “voltaic” refers to electricity.'] },
  { id: 'ENV-045', t: 'Renewable Energy', d: 2, ty: 'reasoning', s: 50,
    q: 'In a village biogas plant, cow dung and kitchen waste are fed into a sealed tank. Why is the tank sealed, and what is the main gas produced?',
    o: ['To keep oxygen out so that anaerobic bacteria can decompose the waste; the gas is mainly methane.', 'To keep the gas cold; the gas is mainly oxygen.', 'To stop light; the gas is mainly hydrogen.', 'To trap heat; the gas is mainly nitrogen.'], a: 0,
    e: 'Biogas (about 55–75% methane, plus CO₂) forms when anaerobic microbes digest organic matter. It burns cleanly for cooking and lighting, reducing indoor smoke from wood. The leftover slurry is a good fertiliser.',
    m: '',
    h: ['Which bacteria work without oxygen?'] },
  { id: 'ENV-046', t: 'Renewable Energy', d: 3, ty: 'numerical', s: 80, v: '2*0.3*8760',
    q: 'A wind turbine rated at 2 MW produces, on average over a year, 30% of its maximum output (its “capacity factor”). How much electrical energy does it generate in a year? (1 year = 8760 hours)',
    o: ['5256 MWh', '17,520 MWh', '600 MWh', '8760 MWh'], a: 0,
    e: 'Average power = 0.3 × 2 MW = 0.6 MW. Energy = 0.6 MW × 8760 h = 5256 MWh — enough for well over a thousand Indian homes. 17,520 MWh assumes the turbine runs at full power all year, which wind never allows.',
    m: '17,520 MWh ignores the capacity factor.',
    h: ['Average power = rated power × capacity factor.', 'Energy = power × time.'] },
  { id: 'ENV-047', t: 'Renewable Energy', d: 2, ty: 'mcq', s: 35,
    q: 'Tidal power stations generate electricity from the rise and fall of the sea. What ultimately causes the tides they use?',
    o: ['Mainly the gravitational pull of the Moon (and to a lesser extent the Sun)', 'Wind blowing over the sea', 'Heat from the Earth’s core', 'River water flowing into the sea'], a: 0,
    e: 'Tides are driven mainly by the Moon’s gravity, so tidal energy is highly predictable. India’s Gulfs of Khambhat and Kutch and the Sundarbans have large tidal ranges suitable for such schemes.',
    m: '',
    h: ['What causes high and low tides?'] },
  { id: 'ENV-048', t: 'Renewable Energy', d: 2, ty: 'mcq', s: 35,
    q: 'Where is geothermal energy most easily used to generate electricity?',
    o: ['In volcanic regions where hot rock and steam are close to the surface, such as Iceland', 'In deserts with strong sunshine', 'On windy coastlines', 'In very cold polar regions'], a: 0,
    e: 'Geothermal energy comes from heat inside the Earth (largely from radioactive decay). In volcanic areas, hot water and steam can be piped to turbines. Iceland gets about a quarter of its electricity and most of its heating this way.',
    m: '',
    h: ['Where is the Earth’s heat closest to the surface?'] },
  { id: 'ENV-049', t: 'Renewable Energy', d: 3, ty: 'statement', s: 80, iq: true,
    q: 'Consider these statements about large hydroelectric dams:\nI. They produce electricity without burning fuel.\nII. Their output depends on rainfall, so droughts reduce it.\nIII. Reservoirs can flood forests and villages and block fish migration.\nIV. Rotting vegetation in some tropical reservoirs releases methane.\nWhich are correct?',
    o: ['All four', 'I and II only', 'I, II and III only', 'II and IV only'], a: 0,
    e: 'Hydropower is renewable and low-carbon in operation (I), but depends on the water cycle (II), has major social and ecological impacts (III), and flooded organic matter decaying without oxygen in warm reservoirs can emit methane (IV). “Renewable” does not mean free of environmental cost.',
    m: '',
    h: ['Is a renewable source automatically free of environmental cost?', 'Think about water supply, flooded land and decaying vegetation.'] },
  { id: 'ENV-050', t: 'Renewable Energy', d: 3, ty: 'numerical', s: 70, iq: true, v: '1000/(1000*0.2)',
    q: 'Sunlight delivers about 1000 W per square metre. What area of 20%-efficient solar panels is needed to produce 1 kW of electrical power in full sunshine?',
    o: ['5 m²', '1 m²', '0.2 m²', '20 m²'], a: 0,
    e: 'Each square metre produces 20% of 1000 W = 200 W. For 1000 W: 1000/200 = 5 m². Real systems need more, because sunlight is weaker in the morning, evening and on cloudy days.',
    m: '1 m² would require 100% efficiency.',
    h: ['How much power does 1 m² produce at 20% efficiency?', 'How many such square metres make 1000 W?'] },
  { id: 'ENV-051', t: 'Renewable Energy', d: 3, ty: 'reasoning', s: 70,
    q: 'A hydrogen fuel cell car emits only water. Why do scientists say its environmental benefit depends on how the hydrogen is made?',
    o: ['Most hydrogen today is made from natural gas, releasing CO₂; only hydrogen made by electrolysis using renewable electricity (“green hydrogen”) is truly low-carbon.', 'Hydrogen is found pure in large underground lakes.', 'Water from the car causes acid rain.', 'Fuel cells use coal directly.'], a: 0,
    e: 'Hydrogen is an energy carrier, not a primary source — it must be produced. Steam reforming of methane releases CO₂, while electrolysis of water is clean only if the electricity is clean. India’s National Green Hydrogen Mission aims to scale up the renewable route.',
    m: '',
    h: ['Where does hydrogen fuel come from?'] },
  { id: 'ENV-052', t: 'Renewable Energy', d: 2, ty: 'reasoning', s: 45,
    q: 'Nuclear power produces very little CO₂ during operation. Why is it nevertheless classed as a non-renewable energy source?',
    o: ['Its fuel, uranium, is mined from limited deposits in the Earth and is not replenished.', 'It produces a lot of smoke.', 'It depends on sunlight.', 'It needs coal to run.'], a: 0,
    e: '“Renewable” refers to whether the source is naturally replenished, not to its emissions. Uranium ore is finite. Nuclear power is low-carbon but non-renewable, and its radioactive waste must be stored safely for thousands of years.',
    m: 'Low-carbon and renewable are different ideas.',
    h: ['Is uranium replaced naturally as we use it?'] },
  { id: 'ENV-053', t: 'Renewable Energy', d: 3, ty: 'application', s: 60,
    q: 'How does a pumped-storage hydropower plant help a grid with lots of solar power?',
    o: ['Surplus electricity at midday pumps water to an upper reservoir; in the evening the water flows back down through turbines to generate power.', 'It stores sunlight in water.', 'It converts water into fuel.', 'It cools the solar panels.'], a: 0,
    e: 'The plant acts like a giant rechargeable battery: electrical energy is stored as gravitational potential energy of water, then recovered (about 75–80% efficiency) when demand is high or the Sun has set.',
    m: '',
    h: ['Electrical energy → which form of stored energy → electrical energy?'] },

  // ---------------------------------------------------------------- Pollution
  { id: 'ENV-054', t: 'Pollution', d: 1, ty: 'mcq', s: 30,
    q: 'Air-quality reports in Indian cities often mention PM2.5. What is it, and why is it dangerous?',
    o: ['Particles smaller than 2.5 micrometres, which can travel deep into the lungs and even enter the bloodstream', 'A gas that smells of rotten eggs', 'The amount of oxygen in the air', 'Large dust particles that settle quickly'], a: 0,
    e: 'PM2.5 particles (about 30 times thinner than a human hair) come from vehicle exhaust, burning of crops and waste, industry and dust. They bypass the nose’s defences, causing lung and heart disease.',
    m: '',
    h: ['“PM” stands for particulate matter.'] },
  { id: 'ENV-055', t: 'Pollution', d: 3, ty: 'reasoning', s: 70, iq: true,
    q: 'Delhi’s air pollution is often worst on calm winter mornings. Which atmospheric condition traps pollutants near the ground?',
    o: ['A temperature inversion — a layer of warmer air above cooler ground-level air stops the polluted air from rising.', 'Strong winds blowing pollution in from the sea.', 'Heavy rainfall.', 'High temperatures causing convection.'], a: 0,
    e: 'Normally air cools with height, so warm polluted air near the ground rises and disperses. On clear, calm winter nights the ground cools fast, leaving cold dense air under warmer air. This stable “lid” traps smoke from vehicles, industry and crop-residue burning. Sunlight and wind later in the day break it up.',
    m: '',
    h: ['Why does warm air usually rise?', 'What happens if the air above is warmer than the air below?'] },
  { id: 'ENV-056', t: 'Pollution', d: 2, ty: 'mcq', s: 40,
    q: 'Which international agreement phased out ozone-destroying chemicals such as CFCs (chlorofluorocarbons)?',
    o: ['The Montreal Protocol (1987)', 'The Kyoto Protocol (1997)', 'The Paris Agreement (2015)', 'The Ramsar Convention (1971)'], a: 0,
    e: 'CFCs used in refrigerators and sprays release chlorine in the stratosphere, which destroys ozone. The Montreal Protocol, ratified by every country, has been very effective: the ozone layer is expected to recover by around the middle of this century. Kyoto and Paris concern greenhouse gases; Ramsar protects wetlands.',
    m: '',
    h: ['It was signed in a Canadian city in the 1980s.'] },
  { id: 'ENV-057', t: 'Pollution', d: 3, ty: 'interdisciplinary', s: 70,
    q: 'In Minamata, Japan, in the 1950s, a factory released mercury waste into the bay. People who ate fish from the bay suffered severe nerve damage, though the water itself held only low mercury levels. Why?',
    o: ['Mercury compounds accumulated in organisms and became more concentrated at each step of the food chain, reaching high levels in fish eaten by people.', 'People drank the sea water.', 'Mercury evaporated and was breathed in by everyone.', 'Fish produce mercury naturally.'], a: 0,
    e: 'Microorganisms convert mercury into methylmercury, which is absorbed easily and not readily excreted. Each predator eats many prey, so concentrations rise up the food chain (biomagnification). Large fish and people at the top received toxic doses.',
    m: '',
    h: ['What happens to persistent toxins as they pass up a food chain?'] },
  { id: 'ENV-058', t: 'Pollution', d: 2, ty: 'reasoning', s: 45,
    q: 'Why are microplastics (pieces smaller than 5 mm) a growing concern?',
    o: ['They do not biodegrade, spread throughout oceans and soils, are eaten by animals and enter the food chain.', 'They dissolve quickly in water.', 'They are absorbed by plants as fertiliser.', 'They only affect deep-sea volcanoes.'], a: 0,
    e: 'Plastic breaks into ever-smaller fragments rather than decomposing. Microplastics have been found in fish, salt, drinking water and human blood. They can carry toxic chemicals and harm the organisms that eat them.',
    m: '',
    h: ['Do plastics break down biologically?'] },
  { id: 'ENV-059', t: 'Pollution', d: 3, ty: 'numerical', s: 70, iq: true, v: '10**((90-60)/10)',
    q: 'On the decibel scale, each increase of 10 dB means the sound intensity is multiplied by 10. Heavy traffic is about 90 dB and normal conversation about 60 dB. How many times more intense is the traffic noise?',
    o: ['1000 times', '30 times', '1.5 times', '100 times'], a: 0,
    e: '90 − 60 = 30 dB = three steps of 10 dB, so the intensity ratio is 10 × 10 × 10 = 1000. Long exposure above about 85 dB can permanently damage hearing.',
    m: '30 treats the scale as linear; 1.5 just divides 90 by 60.',
    h: ['How many 10 dB steps are there between 60 and 90?', 'Each step multiplies intensity by 10.'] },
  { id: 'ENV-060', t: 'Pollution', d: 2, ty: 'application', s: 45,
    q: 'What does a catalytic converter in a car’s exhaust system do?',
    o: ['Converts harmful gases — carbon monoxide, nitrogen oxides and unburnt hydrocarbons — into carbon dioxide, nitrogen and water', 'Removes all carbon dioxide from the exhaust', 'Makes the engine more powerful', 'Turns petrol into diesel'], a: 0,
    e: 'Catalysts such as platinum, palladium and rhodium coat a honeycomb, providing a large surface on which CO is oxidised to CO₂, hydrocarbons to CO₂ and H₂O, and NOₓ reduced to N₂. CO₂ is still emitted, so it does not solve climate change.',
    m: 'A catalytic converter does not remove CO₂ — it produces it.',
    h: ['Which toxic gases come out of an engine?'] },
  { id: 'ENV-061', t: 'Pollution', d: 2, ty: 'mcq', s: 40,
    q: 'A sample of river water downstream of a sewage outlet has a very high biological oxygen demand (BOD). What does this indicate?',
    o: ['The water contains a lot of organic waste, which microbes will use oxygen to decompose — leaving less oxygen for fish.', 'The water is very clean.', 'The water contains a lot of dissolved oxygen.', 'The water is too cold for microbes.'], a: 0,
    e: 'BOD measures how much oxygen microbes consume while breaking down organic matter in a water sample. Clean river water has a low BOD; untreated sewage has a very high BOD, so polluted water quickly becomes oxygen-depleted.',
    m: '',
    h: ['What do microbes need to decompose organic waste?'] },
  { id: 'ENV-062', t: 'Pollution', d: 1, ty: 'mcq', s: 25,
    q: 'Of the “3 Rs” of waste management — Reduce, Reuse and Recycle — which is generally the most effective?',
    o: ['Reduce', 'Recycle', 'Reuse', 'They are all equally effective'], a: 0,
    e: 'Waste that is never created needs no energy, transport or processing. Reusing comes next; recycling still uses energy and some material is lost. Recycling is useful but should be the last of the three.',
    m: '',
    h: ['Which option avoids making waste at all?'] },
  { id: 'ENV-063', t: 'Pollution', d: 2, ty: 'reasoning', s: 50,
    q: 'Thick white foam is sometimes seen floating on stretches of the Yamuna river. What is a major cause?',
    o: ['Detergents (surfactants and phosphates) and other pollutants in untreated sewage and industrial waste', 'Snow from the Himalayas', 'Natural salt deposits', 'Excess oxygen from fish'], a: 0,
    e: 'Surfactants from detergents lower the surface tension of water so that turbulence at weirs whips it into foam. Phosphates also cause algal blooms. Treating sewage before it enters rivers is the main solution.',
    m: '',
    h: ['Which household products make foam?'] },

  // ---------------------------------------------------------------- Biotechnology
  { id: 'ENV-064', t: 'Biotechnology', d: 1, ty: 'mcq', s: 25,
    q: 'Which of these is an example of traditional biotechnology?',
    o: ['Using yeast to make bread and idli batter ferment', 'Building a solar panel', 'Using a magnet to separate iron', 'Distilling sea water'], a: 0,
    e: 'Biotechnology means using living organisms or their enzymes to make products. Fermentation with yeast and bacteria (bread, curd, idli, vinegar) is one of its oldest forms; modern biotechnology adds tools such as genetic engineering.',
    m: '',
    h: ['Which option uses a living organism?'] },
  { id: 'ENV-065', t: 'Biotechnology', d: 2, ty: 'mcq', s: 45,
    q: 'In making recombinant DNA, which enzymes act as “molecular scissors” and “molecular glue”?',
    o: ['Restriction enzymes cut DNA at specific sequences; DNA ligase joins the pieces', 'Amylase cuts DNA; lipase joins it', 'Pepsin cuts DNA; trypsin joins it', 'DNA ligase cuts DNA; restriction enzymes join it'], a: 0,
    e: 'Restriction enzymes recognise particular short base sequences and cut DNA there, often leaving “sticky ends”. A gene cut with the same enzyme can be inserted into a plasmid, and DNA ligase seals the joins. The plasmid is then put into bacteria, which copy the gene.',
    m: '',
    h: ['Which enzyme name sounds like “joining”?'] },
  { id: 'ENV-066', t: 'Biotechnology', d: 3, ty: 'interdisciplinary', s: 70, iq: true,
    q: 'Golden Rice has been genetically engineered to produce beta-carotene in its grain, giving it a yellow colour. Which health problem was it designed to reduce?',
    o: ['Vitamin A deficiency, which causes night blindness and weakens immunity, especially in children', 'Iron-deficiency anaemia', 'Diabetes', 'Scurvy'], a: 0,
    e: 'The body converts beta-carotene into vitamin A. Ordinary rice grain contains almost none, so in regions where rice is the staple food, vitamin A deficiency is common. Genes from maize and a soil bacterium were added to switch on beta-carotene production in the grain.',
    m: '',
    h: ['Which vitamin does the body make from beta-carotene?', 'What are the symptoms of lacking it?'] },
  { id: 'ENV-067', t: 'Biotechnology', d: 2, ty: 'mcq', s: 40,
    q: 'RT-PCR tests were used to detect the COVID-19 virus. What does the PCR technique do?',
    o: ['Makes millions of copies of a specific DNA sequence so that even tiny amounts can be detected', 'Kills viruses in the sample', 'Grows the virus into a visible colony', 'Measures body temperature'], a: 0,
    e: 'The polymerase chain reaction repeatedly heats and cools DNA with primers and a heat-stable polymerase enzyme, doubling the target sequence each cycle — about a billion copies after 30 cycles. For RNA viruses, the RNA is first converted to DNA (reverse transcription, the “RT”).',
    m: '',
    h: ['What does a chain reaction do to the number of copies?'] },
  { id: 'ENV-068', t: 'Biotechnology', d: 3, ty: 'reasoning', s: 60,
    q: 'DNA fingerprinting can identify individuals from tiny samples of blood or hair. Why can it NOT distinguish between identical twins?',
    o: ['Identical twins develop from one zygote and have essentially identical DNA sequences.', 'Twins have no DNA in their hair.', 'Twins’ DNA changes every day.', 'The technique only works on adults.'], a: 0,
    e: 'DNA fingerprinting compares regions of repeated DNA sequences whose lengths vary enormously between people. Because identical twins share the same genome from a single fertilised egg, their patterns match. (Fingerprints on fingers, formed partly by conditions in the womb, do differ.)',
    m: '',
    h: ['How do identical twins form?'] },
  { id: 'ENV-069', t: 'Biotechnology', d: 3, ty: 'what-if', s: 70, iq: true,
    q: 'Gene therapy aims to treat inherited diseases by supplying a working copy of a faulty gene. Why would therapy targeted at a patient’s blood or lung cells NOT be passed on to their children?',
    o: ['Only body (somatic) cells are changed; the egg or sperm cells still carry the faulty gene.', 'Children never inherit genes from parents.', 'The new gene disappears after one day.', 'Blood cells form the sperm and eggs.'], a: 0,
    e: 'Inheritance happens through gametes. Somatic gene therapy changes only the treated tissues. Editing eggs, sperm or embryos (germline editing) would be inherited and raises serious ethical and safety concerns, so it is banned or strictly limited in most countries.',
    m: '',
    h: ['Which cells were changed by the therapy?', 'Which cells pass genes to the next generation?'] },
  { id: 'ENV-070', t: 'Biotechnology', d: 2, ty: 'mcq', s: 40,
    q: 'Dolly the sheep (born 1996) was the first mammal cloned from an adult cell. How was she produced?',
    o: ['The nucleus of an adult udder cell was placed into an egg cell whose own nucleus had been removed.', 'Two sheep were crossed normally.', 'An embryo was split into two.', 'A sheep egg was fertilised by two sperm.'], a: 0,
    e: 'In somatic cell nuclear transfer, the donor nucleus (carrying the adult’s full DNA) is fused with an enucleated egg, which is stimulated to divide and implanted in a surrogate mother. Dolly was genetically identical to the udder-cell donor.',
    m: '',
    h: ['Where did Dolly’s DNA come from?'] },
  { id: 'ENV-071', t: 'Biotechnology', d: 2, ty: 'application', s: 40,
    q: 'Thousands of disease-free banana or orchid plants can be grown from tiny pieces of one plant in sterile jars of nutrient jelly. What is this technique called?',
    o: ['Tissue culture (micropropagation)', 'Cross-pollination', 'Hydroponics', 'Grafting'], a: 0,
    e: 'In tissue culture, small pieces of plant tissue grow on a sterile medium with nutrients and hormones into many genetically identical plantlets. It is fast, needs little space and can produce disease-free stock.',
    m: '',
    h: ['Plants are grown from small pieces of tissue.'] },
  { id: 'ENV-072', t: 'Biotechnology', d: 2, ty: 'mcq', s: 40,
    q: 'Which of these is used as a biofertiliser?',
    o: ['Rhizobium bacteria or blue-green algae (cyanobacteria)', 'Urea', 'Ammonium sulphate', 'Potassium chloride'], a: 0,
    e: 'Biofertilisers are living microbes that enrich soil nutrients, for example nitrogen-fixing Rhizobium (with legumes), Azotobacter and cyanobacteria in paddy fields. Urea and the salts listed are chemical fertilisers.',
    m: '',
    h: ['A biofertiliser must be living.'] },
  { id: 'ENV-073', t: 'Biotechnology', d: 3, ty: 'reasoning', s: 60,
    q: 'Biopesticides, such as spores of the fungus Trichoderma or Bt bacteria, are increasingly used instead of broad-spectrum chemical sprays. What is their main ecological advantage?',
    o: ['They target specific pests and break down naturally, causing less harm to beneficial insects, soil life and people.', 'They kill every insect in the field.', 'They are permanent and never break down.', 'They make crops grow without water.'], a: 0,
    e: 'Many biopesticides act only on particular pests or pathogens and do not persist or biomagnify. Broad-spectrum chemicals also kill pollinators and natural predators of pests, and residues can accumulate in food chains.',
    m: '',
    h: ['Which option is more selective?'] },

  // ---------------------------------------------------------------- AI & Robotics
  { id: 'ENV-074', t: 'AI & Robotics', d: 1, ty: 'mcq', s: 30,
    q: 'What is the key idea of machine learning?',
    o: ['A computer improves at a task by finding patterns in example data, instead of following only rules written by a programmer', 'A computer learns by reading books aloud', 'A machine grows new parts as it learns', 'A computer that never makes mistakes'], a: 0,
    e: 'In machine learning, a model is trained on many examples (for instance, labelled photos), adjusting its internal settings to make better predictions. It can then handle new examples it has never seen — but only as well as its training data allows.',
    m: '',
    h: ['Does it learn from rules or from examples?'] },
  { id: 'ENV-075', t: 'AI & Robotics', d: 2, ty: 'experiment', s: 50,
    q: 'A student trains a program to tell ripe from unripe mangoes using 1000 photos. Why should she test it on a separate set of photos it was never trained on?',
    o: ['To check whether it has learnt general features of ripeness rather than just memorising the training photos', 'Because the program forgets the training photos', 'To make it run faster', 'Testing on training photos is impossible'], a: 0,
    e: 'A model can score perfectly on images it has seen and still fail on new ones. Testing on unseen data is like an exam with new questions: it measures real understanding. This is a basic principle of fair testing in science applied to AI.',
    m: '',
    h: ['Is getting old questions right proof of understanding?'] },
  { id: 'ENV-076', t: 'AI & Robotics', d: 3, ty: 'reasoning', s: 70, iq: true,
    q: 'An AI model gets 99% of its training examples right but only 60% of new examples. What is the most likely problem?',
    o: ['Overfitting — it has memorised details and noise in the training data instead of learning patterns that generalise.', 'It needs a faster processor.', 'The new examples are all wrong.', 'It has learnt too little from the training data.'], a: 0,
    e: 'A big gap between training and test accuracy is the signature of overfitting, like a student who memorised last year’s answers. Remedies include more varied data, simpler models and checking performance on held-out data during training.',
    m: 'Learning too little (underfitting) would show poor accuracy on the training data as well.',
    h: ['Compare performance on seen and unseen data.', 'Think of memorising answers versus understanding.'] },
  { id: 'ENV-077', t: 'AI & Robotics', d: 3, ty: 'numerical', s: 70, v: '3e8*200e-9/2',
    q: 'A self-driving car’s LiDAR sends a laser pulse, which reflects off a cyclist and returns after 200 nanoseconds (200 × 10⁻⁹ s). How far away is the cyclist? (speed of light = 3 × 10⁸ m/s)',
    o: ['30 m', '60 m', '3 m', '300 m'], a: 0,
    e: 'Total path = c × t = 3 × 10⁸ × 200 × 10⁻⁹ = 60 m, out and back. Distance = 60/2 = 30 m. LiDAR builds a 3-D map by firing many such pulses each second — the same echo principle as SONAR, but with light.',
    m: '60 m forgets that the pulse travels to the cyclist and back.',
    h: ['Distance travelled = speed × time.', 'Is that the one-way distance?'] },
  { id: 'ENV-078', t: 'AI & Robotics', d: 2, ty: 'mcq', s: 35,
    q: 'Alan Turing proposed a test in 1950 to judge whether a machine can “think”. What does the Turing test check?',
    o: ['Whether a person conversing by text cannot reliably tell if they are talking to a machine or a human', 'Whether a machine can lift heavy weights', 'How fast a computer can calculate', 'Whether a robot can walk'], a: 0,
    e: 'In Turing’s “imitation game”, a judge exchanges text messages with a hidden human and a hidden machine. If the judge cannot reliably tell which is which, the machine passes. Critics note that imitating conversation is not the same as understanding.',
    m: '',
    h: ['It is based on conversation.'] },
  { id: 'ENV-079', t: 'AI & Robotics', d: 3, ty: 'reasoning', s: 60,
    q: 'AI chatbots can produce fluent, confident answers that are sometimes completely false. What is the most sensible way for a student to use one for science homework?',
    o: ['Treat its answers as suggestions and check facts and calculations against reliable sources and their own reasoning.', 'Copy its answers directly because computers are always correct.', 'Never use any computer for study.', 'Believe it if the answer sounds confident.'], a: 0,
    e: 'Language models generate likely-sounding text from patterns in data and can “hallucinate” facts. Confidence is not evidence. Checking against textbooks, trusted references and your own working is the scientific habit that keeps you safe — whatever the source.',
    m: '',
    h: ['Does sounding confident make a statement true?'] },
  { id: 'ENV-080', t: 'AI & Robotics', d: 2, ty: 'mcq', s: 40,
    q: 'Many modern image-recognition systems use “artificial neural networks”. What are these loosely modelled on?',
    o: ['Networks of neurons in the brain, with connections whose strengths are adjusted during learning', 'The structure of DNA', 'The layers of the Earth', 'The circuits in a light bulb'], a: 0,
    e: 'An artificial neural network has layers of simple units (“neurons”) connected by weighted links. During training, the weights are adjusted so that the network’s outputs become more accurate — loosely similar to how synaptic connections strengthen with learning.',
    m: '',
    h: ['Which organ inspired the name?'] },
  { id: 'ENV-081', t: 'AI & Robotics', d: 3, ty: 'what-if', s: 70, iq: true,
    q: 'A delivery drone must hover steadily in gusty wind. Its gyroscope and accelerometer sensors measure tilt many times a second and adjust motor speeds. What would happen if this feedback loop were switched off?',
    o: ['Small disturbances would grow uncorrected, so the drone would tilt, drift and probably crash.', 'It would hover more steadily.', 'It would automatically land safely.', 'Nothing, because wind has no effect on drones.'], a: 0,
    e: 'Hovering is unstable: a slight tilt directs some thrust sideways, increasing the tilt. A feedback controller compares measured tilt with the desired value and corrects it continuously. Feedback control is central to robots, aircraft autopilots and even body temperature regulation.',
    m: '',
    h: ['What corrects the drone’s tilt?', 'What happens to an uncorrected tilt?'] },
  { id: 'ENV-082', t: 'AI & Robotics', d: 2, ty: 'reasoning', s: 50,
    q: 'Why do many scientists and governments call for rules on the use of facial-recognition AI in public places?',
    o: ['It can invade privacy and may be less accurate for some groups of people, leading to wrongful identification.', 'It uses too little electricity.', 'It only works in the dark.', 'It is impossible to build.'], a: 0,
    e: 'Facial recognition can track people without consent, and systems trained on unbalanced data have shown higher error rates for some skin tones and genders. Responsible use needs testing, transparency, consent and limits on surveillance.',
    m: '',
    h: ['Think about privacy and fairness.'] },

  // ---------------------------------------------------------------- Nanotechnology
  { id: 'ENV-083', t: 'Nanotechnology', d: 1, ty: 'mcq', s: 25,
    q: 'How long is one nanometre?',
    o: ['10⁻⁹ m (one-billionth of a metre)', '10⁻³ m', '10⁻⁶ m', '10⁻¹² m'], a: 0,
    e: 'A nanometre is a billionth of a metre — about the length of 10 hydrogen atoms in a row. A human hair is roughly 80,000–100,000 nm wide. Nanotechnology works with materials from about 1 to 100 nm.',
    m: '10⁻⁶ m is a micrometre.',
    h: ['“Nano” means one-billionth.'] },
  { id: 'ENV-084', t: 'Nanotechnology', d: 2, ty: 'application', s: 40,
    q: 'Silver nanoparticles are added to some bandages and fabrics. Why?',
    o: ['They release silver ions that kill bacteria, and their huge surface area makes them very effective.', 'They make the fabric shiny.', 'They make the bandage heavier.', 'They absorb all moisture permanently.'], a: 0,
    e: 'Silver ions damage bacterial cell membranes and enzymes. Nanoparticles have a very large surface area per gram, so a small amount releases ions effectively. Concerns remain about silver nanoparticles washing into rivers and harming useful microbes.',
    m: '',
    h: ['Silver has long been known to have which property?'] },
  { id: 'ENV-085', t: 'Nanotechnology', d: 3, ty: 'numerical', s: 70, iq: true, v: '1000/10',
    q: 'For a sphere, surface area ÷ volume = 3/r. By what factor is this ratio larger for a nanoparticle of radius 10 nm than for a particle of radius 1 μm (1000 nm)?',
    o: ['100', '10', '1000', '3'], a: 0,
    e: 'The ratio is proportional to 1/r: (3/10)/(3/1000) = 1000/10 = 100. Shrinking a particle 100 times makes its surface-to-volume ratio 100 times larger, which is why nanoparticles are much more reactive per gram.',
    m: '1000 confuses the radius of the larger particle with the ratio.',
    h: ['The ratio depends on 1/r.', 'Divide the radii.'] },
  { id: 'ENV-086', t: 'Nanotechnology', d: 2, ty: 'reasoning', s: 50,
    q: 'Water droplets roll off a lotus leaf as beads, carrying dirt with them. Scientists copy this “lotus effect” for self-cleaning surfaces. What causes it?',
    o: ['Tiny bumps covered with wax nanostructures trap air, so water touches very little of the surface and rolls off.', 'The leaf is coated with oil.', 'The leaf absorbs all water instantly.', 'The leaf is electrically charged.'], a: 0,
    e: 'The lotus leaf surface is rough on the micro- and nanoscale and waxy. Water rests on the tips of the bumps with air pockets beneath, so it forms nearly spherical beads that roll and pick up dirt. Similar engineered surfaces are used on glass, fabrics and paints.',
    m: '',
    h: ['How much of the surface does a water drop actually touch?'] },
  { id: 'ENV-087', t: 'Nanotechnology', d: 3, ty: 'interdisciplinary', s: 60,
    q: 'Medieval stained-glass makers coloured glass ruby red by adding tiny amounts of gold. Why does gold appear red, not gold-coloured, at this scale?',
    o: ['Gold nanoparticles interact with light differently from bulk gold, absorbing green light strongly so the glass looks red.', 'The gold reacted to form a red rust.', 'The glass itself is red.', 'Gold melts into red liquid.'], a: 0,
    e: 'In nanoparticles a few tens of nanometres across, the free electrons oscillate together when struck by light of particular wavelengths (surface plasmon resonance), absorbing strongly around green. The transmitted light appears red. This shows that properties change with size at the nanoscale.',
    m: '',
    h: ['Can the colour of a material depend on particle size?'] },
  { id: 'ENV-088', t: 'Nanotechnology', d: 2, ty: 'mcq', s: 40,
    q: 'Carbon nanotubes are rolled-up sheets of carbon atoms. Which property makes them attractive for future materials?',
    o: ['They are extremely strong yet very light, and can conduct electricity.', 'They are soft like rubber.', 'They are heavier than steel.', 'They dissolve easily in water.'], a: 0,
    e: 'Their strong carbon–carbon bonds give a tensile strength many times that of steel at a fraction of the density. Some nanotubes conduct electricity better than copper. Uses include sports equipment, sensors and potential next-generation electronics.',
    m: '',
    h: ['Carbon–carbon bonds are very strong.'] },
  { id: 'ENV-089', t: 'Nanotechnology', d: 2, ty: 'application', s: 45,
    q: 'Older zinc oxide sunscreens left a white layer on the skin; newer ones using zinc oxide nanoparticles look clear but still block UV. Why?',
    o: ['Nanoparticles are too small to scatter visible light much, but still absorb and block ultraviolet radiation.', 'Nanoparticles block nothing.', 'The nano version contains no zinc oxide.', 'Nanoparticles reflect all colours equally.'], a: 0,
    e: 'Larger particles scatter visible light strongly and look white. Particles much smaller than visible wavelengths scatter little visible light, so the cream looks transparent, while zinc oxide still absorbs UV-A and UV-B.',
    m: '',
    h: ['How does particle size affect scattering of visible light?'] },
  { id: 'ENV-090', t: 'Nanotechnology', d: 3, ty: 'what-if', s: 60, iq: true,
    q: 'Why do scientists study the health and environmental safety of nanoparticles carefully, even when the same material in bulk form is harmless?',
    o: ['Their tiny size can let them penetrate deep into the lungs, cross cell membranes and behave chemically differently from the bulk material.', 'Nanoparticles are always radioactive.', 'Bulk materials are always more dangerous.', 'Nanoparticles cannot be detected at all.'], a: 0,
    e: 'Particles of a few nanometres can reach the deepest parts of the lungs, enter cells and even pass into the bloodstream. Their large surface area makes them more reactive. Safety therefore has to be tested for each nanomaterial, not assumed from the bulk form.',
    m: '',
    h: ['Where can very tiny particles go that larger ones cannot?', 'How does reactivity change with surface area?'] },
  { id: 'ENV-091', t: 'Nanotechnology', d: 2, ty: 'mcq', s: 40,
    q: 'Graphene, isolated in 2004 by Andre Geim and Konstantin Novoselov (Nobel Prize 2010), is:',
    o: ['a single layer of carbon atoms arranged in a honeycomb pattern', 'a new metal element', 'a type of plastic', 'a form of glass'], a: 0,
    e: 'Graphene is one atom thick — the individual layers that stack to make graphite. It is extremely strong, flexible, transparent and an excellent conductor. The first samples were peeled off graphite using sticky tape.',
    m: '',
    h: ['It is related to the material in pencil “lead”.'] },

  // ---------------------------------------------------------------- Emerging Discoveries
  { id: 'ENV-092', t: 'Emerging Discoveries', d: 2, ty: 'mcq', s: 40,
    q: 'How does a qubit in a quantum computer differ from an ordinary computer bit?',
    o: ['A bit is either 0 or 1; a qubit can be in a superposition of 0 and 1 until it is measured.', 'A qubit stores only the number 2.', 'A qubit is a larger, slower bit.', 'There is no difference.'], a: 0,
    e: 'Using quantum effects such as superposition and entanglement, groups of qubits can represent many combinations at once. For some problems (simulating molecules, certain codes) quantum computers could be far faster, though building stable qubits is very hard.',
    m: '',
    h: ['Can a qubit be “partly” 0 and 1?'] },
  { id: 'ENV-093', t: 'Emerging Discoveries', d: 3, ty: 'data', s: 80, iq: true,
    q: 'A telescope records that a star’s brightness dips by exactly 1% for a few hours, every 12 days, very regularly. What is the most likely explanation?',
    o: ['A planet orbits the star with a 12-day period and passes in front of it, blocking a little of its light (the transit method).', 'The star is about to explode.', 'Clouds on Earth block the star every 12 days.', 'The telescope is faulty.'], a: 0,
    e: 'A regular, repeated small dip suggests an orbiting body crossing the star’s face. The period gives the orbit time; the depth of the dip (here 1%) gives the planet’s size relative to the star: area ratio 0.01, so the planet’s radius is about one-tenth of the star’s. NASA’s Kepler and TESS missions found thousands of exoplanets this way.',
    m: '',
    h: ['What could block a little light regularly?', 'What does the regularity tell you?'] },
  { id: 'ENV-094', t: 'Emerging Discoveries', d: 3, ty: 'reasoning', s: 60,
    q: 'In 2012, scientists at CERN’s Large Hadron Collider announced the discovery of the Higgs boson. Why was it important?',
    o: ['It confirmed the existence of the Higgs field, which explains how fundamental particles acquire mass.', 'It proved that atoms do not exist.', 'It is a new kind of virus.', 'It disproved gravity.'], a: 0,
    e: 'The Standard Model of particle physics predicted a field that gives mass to particles such as electrons and quarks, with an associated particle. Finding the Higgs boson completed the model. Peter Higgs and François Englert received the 2013 Nobel Prize. (The name “boson” honours S. N. Bose.)',
    m: '',
    h: ['What property of particles does it help explain?'] },
  { id: 'ENV-095', t: 'Emerging Discoveries', d: 3, ty: 'reasoning', s: 60,
    q: 'Why is silicon, rather than copper, the basic material for computer chips?',
    o: ['Silicon is a semiconductor whose conductivity can be precisely controlled by adding tiny amounts of other elements (doping), allowing transistors to act as switches.', 'Silicon conducts electricity better than copper.', 'Silicon is magnetic.', 'Silicon does not conduct at all, so it is safe.'], a: 0,
    e: 'Doping silicon with phosphorus (extra electrons) or boron (holes) creates n-type and p-type regions. Combining them makes transistors whose current can be switched on and off by a small voltage. Copper always conducts and cannot switch; it is used for the wiring between transistors.',
    m: '',
    h: ['A switch needs something that can be both conducting and non-conducting.'] },
  { id: 'ENV-096', t: 'Emerging Discoveries', d: 2, ty: 'reasoning', s: 45,
    q: 'Why is lithium used in the rechargeable batteries of phones and electric cars?',
    o: ['Lithium is the lightest metal and gives up electrons very readily, so batteries store a lot of energy for their mass.', 'Lithium is the heaviest metal.', 'Lithium never reacts with anything.', 'Lithium is a gas.'], a: 0,
    e: 'Lithium has a very low atomic mass and high reactivity, giving high voltage and high energy per kilogram. Lithium ions move between electrodes as the battery charges and discharges. The 2019 Nobel Prize in Chemistry recognised their development.',
    m: '',
    h: ['Where is lithium in the periodic table?'] },
  { id: 'ENV-097', t: 'Emerging Discoveries', d: 1, ty: 'mcq', s: 25,
    q: 'How does a 3D printer build an object?',
    o: ['By depositing material layer by layer according to a digital design', 'By carving a block of material', 'By pouring liquid into a mould', 'By taking a photograph of the object'], a: 0,
    e: '3D printing (additive manufacturing) builds objects from thin layers of plastic, metal, concrete or even living cells. It is used for prototypes, custom medical implants and rocket parts.',
    m: '',
    h: ['It adds material rather than removing it.'] },
  { id: 'ENV-098', t: 'Emerging Discoveries', d: 3, ty: 'what-if', s: 70, iq: true,
    q: 'Fusion reactors such as ITER (with India as a partner) aim to fuse hydrogen isotopes as the Sun does. Why must the fuel be heated to over 100 million °C — hotter than the Sun’s core?',
    o: ['Nuclei are positively charged and repel each other; only extremely fast-moving nuclei can get close enough to fuse, and reactors cannot use the Sun’s enormous gravitational pressure.', 'Fusion only works on red-hot metal.', 'The fuel must be melted.', 'Higher temperature reduces the amount of fuel needed to zero.'], a: 0,
    e: 'To fuse, two nuclei must overcome their electrostatic repulsion. The Sun’s core manages at about 15 million °C because of immense pressure and density. On Earth, without that pressure, the plasma must be much hotter, held away from the walls by powerful magnetic fields.',
    m: '',
    h: ['What force pushes two positive nuclei apart?', 'What does the Sun have that a reactor lacks?'] },
  { id: 'ENV-099', t: 'Emerging Discoveries', d: 3, ty: 'reasoning', s: 60,
    q: 'Electric cars produce no exhaust. Why do scientists say their overall climate benefit depends on the electricity grid?',
    o: ['If the electricity comes mainly from coal, CO₂ is still emitted at the power station; with renewable electricity, total emissions are far lower.', 'Electric cars run on petrol at night.', 'Electric motors emit more CO₂ than engines.', 'The grid has no effect on emissions.'], a: 0,
    e: 'Electric vehicles move emissions from the tailpipe to the power plant. They remove local air pollution in cities and are generally more efficient, but their climate benefit grows as the grid shifts to solar, wind, hydro and nuclear. Battery manufacturing also has emissions.',
    m: '',
    h: ['Where does the electricity come from?'] },
  { id: 'ENV-100', t: 'Emerging Discoveries', d: 1, ty: 'mcq', s: 25,
    q: 'What does the “Internet of Things” (IoT) refer to?',
    o: ['Everyday devices with sensors connected to the internet to share data and be controlled remotely', 'A list of websites', 'A new type of computer virus', 'Books about the internet'], a: 0,
    e: 'Examples include smart meters, fitness bands, soil-moisture sensors that switch on irrigation, and traffic sensors. IoT devices produce huge amounts of data, which raises benefits for efficiency and concerns for security and privacy.',
    m: '',
    h: ['Which “things” get connected?'] },
];
